def test_smart_agent_offers_below_quote_and_never_above_it():
    quote = {"term_sheet_id": "o1", "terms": {"unit_price": 44.0, "payment_days": 30}}
    threads = {"sup:A": [{"from": "sup:A", "status": "open", "term_sheets": [quote]}]}
    from arena_kit.agents import SmartAgent

    sheets = SmartAgent().decide(CASE, threads)["message"]["term_sheets"]
    assert 1 <= len(sheets) <= 3
    assert all(s["terms"]["unit_price"] < 44.0 for s in sheets)
    assert all(total_cost(CASE, s["terms"]) <= total_cost(CASE, quote["terms"]) for s in sheets)


QUOTE = {"unit_price": 44.0, "payment_days": 30}


def _smart(status, terms=None, case=CASE, sent=0, **extra):
    from arena_kit.agents import SmartAgent

    sheets = [{"term_sheet_id": "o1", "terms": terms}] if terms else []
    first = [{"term_sheet_id": "o0", "terms": QUOTE}] if terms else []
    events = [{"from": "sup:A", "status": "open", "term_sheets": first}]
    events += [{"from": "buyer", "term_sheets": [{"terms": {"unit_price": 30.0}}]}] * sent
    events += [{"from": "sup:A", "status": status, "term_sheets": sheets}] if sent else []
    return SmartAgent().decide({**case, **extra}, {"sup:A": events})["message"]



def test_smart_accepts_agreed_cheaper_sheet_and_final_offer():
    cheap = {"unit_price": 40.0, "payment_days": 60}
    assert _smart("agreed", cheap, sent=1)["action"] == {"type": "accept", "term_sheet_id": "o1"}

